#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> nodesBetweenCriticalPoints(ListNode* head) {
        if (!head || !head->next || !head->next->next) return {-1, -1};

        ListNode* prev = head;
        ListNode* curr = head->next;
        int idx = 1;
        int firstCp = -1, lastCp = -1, prevCp = -1;
        int minDist = 1e9;

        while (curr && curr->next) {
            if ((curr->val > prev->val && curr->val > curr->next->val) ||
                (curr->val < prev->val && curr->val < curr->next->val)) {
                if (firstCp == -1) firstCp = idx;
                if (prevCp != -1) minDist = std::min(minDist, idx - prevCp);
                prevCp = idx;
                lastCp = idx;
            }
            prev = curr;
            curr = curr->next;
            idx++;
        }

        if (firstCp == lastCp || firstCp == -1) return {-1, -1};
        return {minDist, lastCp - firstCp};
    }
};

class Solution {
    public int[] nodesBetweenCriticalPoints(ListNode head) {
        if (head == null || head.next == null || head.next.next == null) {
            return new int[]{-1, -1};
        }

        ListNode prev = head;
        ListNode curr = head.next;
        int idx = 1;
        int firstCp = -1, lastCp = -1, prevCp = -1;
        int minDist = Integer.MAX_VALUE;

        while (curr != null && curr.next != null) {
            if ((curr.val > prev.val && curr.val > curr.next.val) ||
                (curr.val < prev.val && curr.val < curr.next.val)) {
                if (firstCp == -1) firstCp = idx;
                if (prevCp != -1) minDist = Math.min(minDist, idx - prevCp);
                prevCp = idx;
                lastCp = idx;
            }
            prev = curr;
            curr = curr.next;
            idx++;
        }

        if (firstCp == lastCp || firstCp == -1) return new int[]{-1, -1};
        return new int[]{minDist, lastCp - firstCp};
    }
}

